import React, { useState, useEffect } from 'react';
import { PlusIcon } from './icons';

interface ChangeLog {
  id: number;
  date: string;
  title: string;
  description: string;
}

interface ChangeLogModalProps {
  isOpen: boolean;
  onClose: () => void;
}

const ChangeLogModal: React.FC<ChangeLogModalProps> = ({ isOpen, onClose }) => {
  const [logs, setLogs] = useState<ChangeLog[]>([]);
  const [isFormVisible, setIsFormVisible] = useState(false);
  const [newLogTitle, setNewLogTitle] = useState('');
  const [newLogDescription, setNewLogDescription] = useState('');

  useEffect(() => {
    if (isOpen) {
      try {
        const storedLogs = localStorage.getItem('devChangeLogs');
        if (storedLogs) {
          setLogs(JSON.parse(storedLogs));
        }
      } catch (error) {
        console.error("無法從 localStorage 讀取變更紀錄", error);
      }
    }
  }, [isOpen]);

  const saveLogs = (updatedLogs: ChangeLog[]) => {
    try {
      localStorage.setItem('devChangeLogs', JSON.stringify(updatedLogs));
      setLogs(updatedLogs);
    } catch (error) {
      console.error("無法儲存變更紀錄至 localStorage", error);
    }
  };

  const handleAddLog = () => {
    if (!newLogTitle.trim() || !newLogDescription.trim()) {
      alert('標題和描述不能為空！');
      return;
    }
    const newLog: ChangeLog = {
      id: Date.now(),
      date: new Date().toLocaleString('zh-TW', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }),
      title: newLogTitle,
      description: newLogDescription,
    };
    saveLogs([newLog, ...logs]);
    setNewLogTitle('');
    setNewLogDescription('');
    setIsFormVisible(false);
  };

  if (!isOpen) return null;

  return (
    <div
      className="fixed inset-0 bg-black bg-opacity-60 z-[100] flex justify-center items-center"
      aria-labelledby="changelog-modal-title"
      role="dialog"
      aria-modal="true"
      onClick={onClose}
    >
      <div
        className="bg-white rounded-xl shadow-xl w-full max-w-2xl m-4 transform transition-all flex flex-col"
        onClick={e => e.stopPropagation()}
      >
        <div className="p-6 border-b border-gray-200 flex justify-between items-center">
          <h3 className="text-lg font-semibold text-gray-900" id="changelog-modal-title">
            需求變更紀錄
          </h3>
          <button
            onClick={onClose}
            className="text-gray-400 hover:text-gray-600"
            aria-label="關閉"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="p-6 max-h-[70vh] overflow-y-auto">
          {isFormVisible ? (
            <div className="space-y-4">
              <h4 className="font-bold text-gray-700">新增紀錄</h4>
              <div>
                <label htmlFor="logTitle" className="block text-sm font-medium text-gray-700 mb-1">標題</label>
                <input
                  type="text"
                  id="logTitle"
                  value={newLogTitle}
                  onChange={(e) => setNewLogTitle(e.target.value)}
                  className="w-full border border-gray-300 rounded-md px-3 py-2 text-sm placeholder-gray-400 focus:ring-1 focus:ring-blue-500 focus:border-blue-500"
                  placeholder="簡短描述這次的變更..."
                />
              </div>
              <div>
                <label htmlFor="logDescription" className="block text-sm font-medium text-gray-700 mb-1">詳細說明</label>
                <textarea
                  id="logDescription"
                  rows={6}
                  value={newLogDescription}
                  onChange={(e) => setNewLogDescription(e.target.value)}
                  className="w-full border border-gray-300 rounded-md px-3 py-2 text-sm placeholder-gray-400 focus:ring-1 focus:ring-blue-500 focus:border-blue-500"
                  placeholder="詳細記錄變更內容、原因、影響範圍等。"
                ></textarea>
              </div>
              <div className="flex justify-end space-x-3">
                <button onClick={() => setIsFormVisible(false)} className="bg-gray-200 text-gray-700 px-4 py-2 rounded-md text-sm hover:bg-gray-300">取消</button>
                <button onClick={handleAddLog} className="bg-green-600 text-white px-4 py-2 rounded-md text-sm hover:bg-green-700">儲存紀錄</button>
              </div>
            </div>
          ) : (
            <div>
              <div className="flex justify-end mb-4">
                <button 
                  onClick={() => setIsFormVisible(true)}
                  className="flex items-center bg-green-600 text-white px-4 py-2 rounded-md text-sm hover:bg-green-700"
                >
                  <PlusIcon className="w-5 h-5 mr-1" />
                  新增紀錄
                </button>
              </div>

              {logs.length > 0 ? (
                <div className="space-y-4">
                  {logs.map(log => (
                    <div key={log.id} className="bg-gray-50 border border-gray-200 p-4 rounded-lg">
                      <div className="flex justify-between items-center mb-2">
                        <h5 className="font-bold text-gray-800">{log.title}</h5>
                        <span className="text-xs text-gray-500">{log.date}</span>
                      </div>
                      <p className="text-sm text-gray-600 whitespace-pre-wrap">{log.description}</p>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-10 text-gray-500">
                  <p>目前沒有任何變更紀錄。</p>
                  <p className="mt-1">點擊「新增紀錄」來建立第一筆吧！</p>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ChangeLogModal;

import React, { useState, useEffect } from 'react';
import { PlusIcon } from './icons';
import { GoogleGenAI, Type } from '@google/genai';
import mermaid from 'mermaid';

interface ChangeLog {
  id: number;
  date: string;
  title: string;
  description: string;
  diagram?: string;
}

interface GeneratedLog {
    title: string;
    description: string;
    diagram: string;
}

interface ChangeLogModalProps {
  isOpen: boolean;
  onClose: () => void;
}

const ChangeLogModal: React.FC<ChangeLogModalProps> = ({ isOpen, onClose }) => {
  const [logs, setLogs] = useState<ChangeLog[]>([]);
  const [isFormVisible, setIsFormVisible] = useState(false);

  const [userInput, setUserInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [generatedLog, setGeneratedLog] = useState<GeneratedLog | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (isOpen) {
      try {
        const storedLogs = localStorage.getItem('devChangeLogs');
        if (storedLogs) {
          setLogs(JSON.parse(storedLogs));
        }
      } catch (error) {
        console.error("無法從 localStorage 讀取變更紀錄", error);
      }

      mermaid.initialize({ startOnLoad: false, theme: 'neutral' });
      setTimeout(() => {
          try {
              mermaid.run();
          } catch(e) {
              console.error("Mermaid rendering error:", e);
          }
      }, 100);
    }
  }, [isOpen, logs, generatedLog]);

  const saveLogs = (updatedLogs: ChangeLog[]) => {
    try {
      localStorage.setItem('devChangeLogs', JSON.stringify(updatedLogs));
      setLogs(updatedLogs);
    } catch (error) {
      console.error("無法儲存變更紀錄至 localStorage", error);
    }
  };

  const handleGenerateLog = async () => {
    if (!userInput.trim()) {
        setError('請輸入您的需求變更描述。');
        return;
    }
    setIsLoading(true);
    setGeneratedLog(null);
    setError(null);

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: `請根據以下使用者需求，產生一份需求變更紀錄。使用者需求： "${userInput}"`,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        title: {
                            type: Type.STRING,
                            description: '為這個需求變更產生一個簡潔的標題。'
                        },
                        description: {
                            type: Type.STRING,
                            description: '詳細描述這個需求變更的內容、原因與目的，使用 Markdown 格式。'
                        },
                        diagram: {
                            type: Type.STRING,
                            description: '使用 Mermaid 的 flowchart TD 語法，產生一個說明 UI 或流程變更的圖表。'
                        },
                    },
                    required: ["title", "description", "diagram"]
                },
            },
        });

        const resultText = response.text.trim();
        const logData = JSON.parse(resultText) as GeneratedLog;
        setGeneratedLog(logData);
    } catch (err) {
        console.error("Error generating log:", err);
        setError('生成紀錄時發生錯誤，請檢查 API Key 或稍後再試。');
    } finally {
        setIsLoading(false);
    }
  };

  const handleSaveGeneratedLog = () => {
    if (!generatedLog) return;

    const newLog: ChangeLog = {
        id: Date.now(),
        date: new Date().toLocaleString('zh-TW', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }),
        title: generatedLog.title,
        description: generatedLog.description,
        diagram: generatedLog.diagram,
    };
    saveLogs([newLog, ...logs]);

    setIsFormVisible(false);
    setGeneratedLog(null);
    setUserInput('');
    setError(null);
  };

  const handleDiscard = () => {
    setGeneratedLog(null);
    setError(null);
  };

  const resetForm = () => {
    setIsFormVisible(false);
    setGeneratedLog(null);
    setUserInput('');
    setError(null);
    setIsLoading(false);
  }

  return (
    <div
      className={`fixed inset-0 bg-black bg-opacity-60 z-[100] flex justify-center items-center ${isOpen ? 'visible' : 'invisible'}`}
      aria-labelledby="changelog-modal-title"
      role="dialog"
      aria-modal="true"
      onClick={() => { onClose(); resetForm(); }}
    >
      <div
        className="bg-white rounded-xl shadow-xl w-full max-w-2xl m-4 transform transition-all flex flex-col"
        onClick={e => e.stopPropagation()}
      >
        <div className="p-6 border-b border-gray-200 flex justify-between items-center">
          <h3 className="text-lg font-semibold text-gray-900" id="changelog-modal-title">
            需求變更紀錄
          </h3>
          <button
            onClick={() => { onClose(); resetForm(); }}
            className="text-gray-400 hover:text-gray-600"
            aria-label="關閉"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="p-6 max-h-[70vh] overflow-y-auto">
          {isFormVisible ? (
            <div>
              {!generatedLog && !isLoading && (
                  <div className="space-y-4">
                      <h4 className="font-bold text-gray-700">透過對話生成紀錄</h4>
                      <div>
                          <label htmlFor="logPrompt" className="block text-sm font-medium text-gray-700 mb-1">
                              請描述您想記錄的需求變更：
                          </label>
                          <textarea
                              id="logPrompt"
                              rows={4}
                              value={userInput}
                              onChange={(e) => setUserInput(e.target.value)}
                              className="w-full border border-gray-300 rounded-md px-3 py-2 text-sm placeholder-gray-400 focus:ring-1 focus:ring-blue-500 focus:border-blue-500"
                              placeholder="例如：請針對B-01頁面，為新手引導加入完成兩個步驟的提示..."
                          ></textarea>
                      </div>
                      {error && <p className="text-sm text-red-600">{error}</p>}
                      <div className="flex justify-end space-x-3">
                          <button onClick={resetForm} className="bg-gray-200 text-gray-700 px-4 py-2 rounded-md text-sm hover:bg-gray-300">取消</button>
                          <button onClick={handleGenerateLog} className="bg-blue-600 text-white px-4 py-2 rounded-md text-sm hover:bg-blue-700">生成紀錄</button>
                      </div>
                  </div>
              )}
              {isLoading && (
                  <div className="text-center py-10">
                      <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500 mx-auto"></div>
                      <p className="mt-4 text-gray-600">正在為您生成紀錄，請稍候...</p>
                  </div>
              )}
              {generatedLog && !isLoading && (
                  <div className="space-y-4">
                      <h4 className="font-bold text-gray-700">已生成紀錄預覽</h4>
                      <div className="bg-gray-50 border border-gray-200 p-4 rounded-lg space-y-4">
                          <div>
                              <h5 className="font-bold text-gray-800">{generatedLog.title}</h5>
                          </div>
                          <div>
                              <p className="text-sm text-gray-600 whitespace-pre-wrap">{generatedLog.description}</p>
                          </div>
                          {generatedLog.diagram && (
                              <div className="mt-4 p-4 bg-white border rounded-md">
                                  <h6 className="text-xs font-semibold text-gray-500 mb-2">流程圖</h6>
                                  <div className="mermaid text-center">
                                      {generatedLog.diagram}
                                  </div>
                              </div>
                          )}
                      </div>
                      {error && <p className="text-sm text-red-600 mt-2">{error}</p>}
                      <div className="flex justify-end space-x-3 pt-2">
                          <button onClick={handleDiscard} className="bg-gray-200 text-gray-700 px-4 py-2 rounded-md text-sm hover:bg-gray-300">重新生成</button>
                          <button onClick={handleSaveGeneratedLog} className="bg-green-600 text-white px-4 py-2 rounded-md text-sm hover:bg-green-700">儲存此紀錄</button>
                      </div>
                  </div>
              )}
            </div>
          ) : (
            <div>
              <div className="flex justify-end mb-4">
                <button 
                  onClick={() => setIsFormVisible(true)}
                  className="flex items-center bg-green-600 text-white px-4 py-2 rounded-md text-sm hover:bg-green-700"
                >
                  <PlusIcon className="w-5 h-5 mr-1" />
                  新增紀錄
                </button>
              </div>

              {logs.length > 0 ? (
                <div className="space-y-4">
                  {logs.map(log => (
                    <div key={log.id} className="bg-gray-50 border border-gray-200 p-4 rounded-lg">
                      <div className="flex justify-between items-center mb-2">
                        <h5 className="font-bold text-gray-800">{log.title}</h5>
                        <span className="text-xs text-gray-500">{log.date}</span>
                      </div>
                      <p className="text-sm text-gray-600 whitespace-pre-wrap">{log.description}</p>
                      {log.diagram && (
                          <div className="mt-4 p-4 bg-white border rounded-md">
                              <h6 className="text-xs font-semibold text-gray-500 mb-2">流程圖</h6>
                              <div className="mermaid text-center">
                                  {log.diagram}
                              </div>
                          </div>
                      )}
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-10 text-gray-500">
                  <p>目前沒有任何變更紀錄。</p>
                  <p className="mt-1">點擊「新增紀錄」來建立第一筆吧！</p>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ChangeLogModal;

