  const [logs, setLogs] = useState<ChangeLog[]>([]);
  const [isFormVisible, setIsFormVisible] = useState(false);

  const [userInput, setUserInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [generatedLog, setGeneratedLog] = useState<GeneratedLog | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (isOpen) {
      try {
        const storedLogs = localStorage.getItem('devChangeLogs');
        if (storedLogs) {
          setLogs(JSON.parse(storedLogs));
        }
      } catch (error) {
        console.error("無法從 localStorage 讀取變更紀錄", error);
      }
    }
  }, [isOpen]);

  const saveLogs = (updatedLogs: ChangeLog[]) => {
    try {
      localStorage.setItem('devChangeLogs', JSON.stringify(updatedLogs));
      setLogs(updatedLogs);
    } catch (error) {
      console.error("無法儲存變更紀錄至 localStorage", error);
    }
  };

  const handleGenerateLog = async () => {
    if (!userInput.trim()) {
        setError('請輸入您的需求變更描述。');
        return;
    }
    setIsLoading(true);
    setGeneratedLog(null);
    setError(null);

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: `你是一位專業的前端工程師與 UI/UX 設計師。請根據以下使用者提出的需求變更，產生一份專業的需求變更紀錄。需求描述： "${userInput}"。你的回覆必須包含精確的標題、使用 Markdown 詳細說明的變更內容，以及一個描述 UI 流程的 JSON 物件。`,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        title: {
                            type: Type.STRING,
                            description: '為這個需求變更產生一個簡潔、專業的標題。'
                        },
                        description: {
                            type: Type.STRING,
                            description: '詳細描述這個需求變更的內容、原因與目的，使用 Markdown 格式，包含標題、列表等。'
                        },
                        diagram: {
                            type: Type.OBJECT,
                            description: '產生一個描述 UI 流程的 JSON 物件。這個物件包含 "nodes" 和 "edges"。 "nodes" 陣列中的每個物件代表一個畫面，包含 id, title, componentName, props, 和 position {x, y}。 "edges" 陣列中的每個物件代表一個連接，包含 from, to, 和 label。可用的 componentName 有： "Login", "MyAccountContent", "TicketManagementContent", "AddVoucherContent", "BasicSettingsContent"。請為元件提供必要的 mock props，例如 isBasicSettingsComplete: true。',
                            properties: {
                                nodes: {
                                    type: Type.ARRAY,
                                    items: {
                                        type: Type.OBJECT,
                                        properties: {
                                            id: { type: Type.STRING },
                                            title: { type: Type.STRING },
                                            componentName: { type: Type.STRING },
                                            props: { type: Type.OBJECT },
                                            position: {
                                                type: Type.OBJECT,
                                                properties: {
                                                    x: { type: Type.NUMBER },
                                                    y: { type: Type.NUMBER },
                                                }
                                            }
                                        }
                                    }
                                },
                                edges: {
                                    type: Type.ARRAY,
                                    items: {
                                        type: Type.OBJECT,
                                        properties: {
                                            from: { type: Type.STRING },
                                            to: { type: Type.STRING },
                                            label: { type: Type.STRING }
                                        }
                                    }
                                }
                            }
                        },
                    },
                    required: ["title", "description", "diagram"]
                },
            },
        });

        const resultText = response.text.trim();
        const logData = JSON.parse(resultText) as GeneratedLog;
        setGeneratedLog(logData);
    } catch (err) {
        console.error("Error generating log:", err);
        setError('生成紀錄時發生錯誤，請檢查 API Key 或稍後再試。');
    } finally {
        setIsLoading(false);
    }
  };

  const handleSaveGeneratedLog = () => {
    if (!generatedLog) return;

    const newLog: ChangeLog = {
        id: Date.now(),
        date: new Date().toLocaleString('zh-TW', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }),
        title: generatedLog.title,
        description: generatedLog.description,
        diagram: generatedLog.diagram,
    };
    const updatedLogs = [newLog, ...logs];
    saveLogs(updatedLogs);
    setLogs(updatedLogs); // Immediately update state

    setIsFormVisible(false);
    setGeneratedLog(null);
    setUserInput('');
    setError(null);
  };

  const handleDiscard = () => {
    setGeneratedLog(null);
    setError(null);
  };

  const resetForm = () => {
    setIsFormVisible(false);
    setGeneratedLog(null);
    setUserInput('');
    setError(null);
    setIsLoading(false);
  }

  return (
    <div
      className={`fixed inset-0 bg-black bg-opacity-60 z-[100] flex justify-center items-center ${isOpen ? 'visible' : 'invisible'}`}
      aria-labelledby="changelog-modal-title"
      role="dialog"
      aria-modal="true"
      onClick={() => { onClose(); resetForm(); }}
    >
      <div
        className="bg-white w-screen h-screen flex flex-col"
        onClick={e => e.stopPropagation()}
      >
        <div className="p-6 border-b border-gray-200 flex justify-between items-center shrink-0">
          <h3 className="text-lg font-semibold text-gray-900" id="changelog-modal-title">
            需求變更紀錄
          </h3>
          <button
            onClick={() => { onClose(); resetForm(); }}
            className="text-gray-400 hover:text-gray-600"
            aria-label="關閉"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="p-6 flex-1 overflow-y-auto">
          {isFormVisible ? (
            <div className="max-w-4xl mx-auto">
              {!generatedLog && !isLoading && (
                  <div className="space-y-4">
                      <h4 className="font-bold text-gray-700">透過對話生成紀錄</h4>
                      <div>
                          <label htmlFor="logPrompt" className="block text-sm font-medium text-gray-700 mb-1">
                              請描述您想記錄的需求變更：
                          </label>
                          <textarea
                              id="logPrompt"
                              rows={4}
                              value={userInput}
                              onChange={(e) => setUserInput(e.target.value)}
                              className="w-full border border-gray-300 rounded-md px-3 py-2 text-sm placeholder-gray-400 focus:ring-1 focus:ring-blue-500 focus:border-blue-500"
                              placeholder="例如：請針對B-01頁面，為新手引導加入完成兩個步驟的提示..."
                          ></textarea>
                      </div>
                      {error && <p className="text-sm text-red-600">{error}</p>}
                      <div className="flex justify-end space-x-3">
                          <button onClick={resetForm} className="bg-gray-200 text-gray-700 px-4 py-2 rounded-md text-sm hover:bg-gray-300">取消</button>
                          <button onClick={handleGenerateLog} className="bg-blue-600 text-white px-4 py-2 rounded-md text-sm hover:bg-blue-700">生成紀錄</button>
                      </div>
                  </div>
              )}
              {isLoading && (
                  <div className="text-center py-10">
                      <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500 mx-auto"></div>
                      <p className="mt-4 text-gray-600">正在為您生成紀錄，請稍候...</p>
                  </div>
              )}
              {generatedLog && !isLoading && (
                  <div className="space-y-4">
                      <h4 className="font-bold text-gray-700">已生成紀錄預覽</h4>
                      <div className="bg-gray-50 border border-gray-200 p-4 rounded-lg space-y-4">
                          <div>
                              <h5 className="font-bold text-gray-800 text-xl mb-4">{generatedLog.title}</h5>
                          </div>
                          <div>
                              <MarkdownRenderer content={generatedLog.description} />
                          </div>
                          {generatedLog.diagram && (
                              <div className="mt-4 p-4 bg-white border rounded-md">
                                  <h6 className="text-sm font-semibold text-gray-600 mb-2">流程圖</h6>
                                   <div className="h-[500px] w-full bg-slate-100 rounded-lg overflow-hidden">
                                        <UIFlowCanvas flowData={generatedLog.diagram} />
                                   </div>
                              </div>
                          )}
                      </div>
                      {error && <p className="text-sm text-red-600 mt-2">{error}</p>}
                      <div className="flex justify-end space-x-3 pt-2">
                          <button onClick={handleDiscard} className="bg-gray-200 text-gray-700 px-4 py-2 rounded-md text-sm hover:bg-gray-300">重新生成</button>
                          <button onClick={handleSaveGeneratedLog} className="bg-green-600 text-white px-4 py-2 rounded-md text-sm hover:bg-green-700">儲存此紀錄</button>
                      </div>
                  </div>
              )}
            </div>
          ) : (
            <div className="max-w-4xl mx-auto">
              <div className="flex justify-end mb-4">
                <button 
                  onClick={() => setIsFormVisible(true)}
                  className="flex items-center bg-green-600 text-white px-4 py-2 rounded-md text-sm hover:bg-green-700"
                >
                  <PlusIcon className="w-5 h-5 mr-1" />
                  新增紀錄
                </button>
              </div>

              {logs.length > 0 ? (
                <div className="space-y-4">
                  {logs.map(log => (
                    <div key={log.id} className="bg-gray-50 border border-gray-200 p-4 rounded-lg">
                      <div className="flex justify-between items-center mb-2">
                        <h5 className="font-bold text-gray-800 text-lg">{log.title}</h5>
                        <span className="text-xs text-gray-500">{log.date}</span>
                      </div>
                      <MarkdownRenderer content={log.description} />
                      {log.diagram && (
                          <div className="mt-4 p-4 bg-white border rounded-md">
                              <h6 className="text-sm font-semibold text-gray-600 mb-2">流程圖</h6>
                              <div className="h-[500px] w-full bg-slate-100 rounded-lg overflow-hidden">
                                <UIFlowCanvas flowData={log.diagram} />
                              </div>
                          </div>
                      )}
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-10 text-gray-500">
                  <p>目前沒有任何變更紀錄。</p>
                  <p className="mt-1">點擊「新增紀錄」來建立第一筆吧！</p>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ChangeLogModal;

import React, { useState, useRef, useEffect, FC } from 'react';
import { componentRegistry } from './componentRegistry';
import ScreenWrapper from './ScreenWrapper';
import FlowArrow from './FlowArrow';

export interface FlowNode {
  id: string;
  title: string;
  componentName: keyof typeof componentRegistry;
  props: any;
  position: { x: number; y: number };
}

export interface FlowEdge {
  from: string;
  to: string;
  label: string;
}

export interface FlowData {
  nodes: FlowNode[];
  edges: FlowEdge[];
}

interface UIFlowCanvasProps {
  flowData: FlowData;
}

const UIFlowCanvas: FC<UIFlowCanvasProps> = ({ flowData }) => {
  const [transform, setTransform] = useState({ scale: 0.7, translateX: 50, translateY: 50 });
  const [isPanning, setIsPanning] = useState(false);
  const [panStart, setPanStart] = useState({ x: 0, y: 0 });
  const canvasRef = useRef<HTMLDivElement>(null);

  const handleWheel = (e: React.WheelEvent) => {
    e.preventDefault();
    const scaleAmount = -e.deltaY * 0.001;
    const newScale = Math.max(0.2, Math.min(2, transform.scale + scaleAmount));

    const rect = canvasRef.current!.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;

    const newTranslateX = mouseX - (mouseX - transform.translateX) * (newScale / transform.scale);
    const newTranslateY = mouseY - (mouseY - transform.translateY) * (newScale / transform.scale);

    setTransform({
      scale: newScale,
      translateX: newTranslateX,
      translateY: newTranslateY,
    });
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (e.button !== 0) return;
    setIsPanning(true);
    setPanStart({ x: e.clientX, y: e.clientY });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isPanning) return;
    const dx = e.clientX - panStart.x;
    const dy = e.clientY - panStart.y;
    setTransform(prev => ({
      ...prev,
      translateX: prev.translateX + dx,
      translateY: prev.translateY + dy,
    }));
    setPanStart({ x: e.clientX, y: e.clientY });
  };

  const handleMouseUp = () => {
    setIsPanning(false);
  };

  const nodeElements = useRef<{ [key: string]: HTMLDivElement }>({});

  useEffect(() => {
    // This effect is to ensure that when new flowData comes in,
    // we have the refs to the nodes for arrow calculations.
    // It's a bit of a trick to force a re-render after initial layout.
    const timer = setTimeout(() => {
      // Force a re-render to draw arrows correctly after nodes are positioned
      setTransform(t => ({...t}));
    }, 50);
    return () => clearTimeout(timer);
  }, [flowData]);


  return (
    <div
      ref={canvasRef}
      className="w-full h-full cursor-grab relative overflow-hidden bg-dots"
      style={{ backgroundSize: '20px 20px', backgroundImage: 'radial-gradient(circle, #d1d5db 1px, rgba(0,0,0,0) 1px)' }}
      onWheel={handleWheel}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
    >
      <div
        className="absolute"
        style={{
          transform: `translate(${transform.translateX}px, ${transform.translateY}px) scale(${transform.scale})`,
          transformOrigin: '0 0',
        }}
      >
        {flowData.nodes.map(node => {
          const Component = componentRegistry[node.componentName]?.component;
          const defaultProps = componentRegistry[node.componentName]?.defaultProps || {};

          if (!Component) {
            return (
              <div key={node.id} style={{ position: 'absolute', left: node.position.x, top: node.position.y }}>
                <ScreenWrapper title={node.title}>
                  <div className="p-4 text-red-500">Component "{node.componentName}" not found.</div>
                </ScreenWrapper>
              </div>
            );
          }

          return (
            <div
              key={node.id}
              ref={el => { if(el) nodeElements.current[node.id] = el; }}
              style={{
                position: 'absolute',
                left: node.position.x,
                top: node.position.y,
                width: '375px', // Standard mobile width
              }}
            >
              <ScreenWrapper title={node.title}>
                <Component {...defaultProps} {...node.props} />
              </ScreenWrapper>
            </div>
          );
        })}

        {flowData.edges.map((edge, index) => {
          const fromNodeEl = nodeElements.current[edge.from];
          const toNodeEl = nodeElements.current[edge.to];
          if (!fromNodeEl || !toNodeEl) return null;

          const fromRect = fromNodeEl.getBoundingClientRect();
          const toRect = toNodeEl.getBoundingClientRect();
          const containerRect = canvasRef.current!.getBoundingClientRect();

          const from = {
            x: (fromRect.right - containerRect.left) / transform.scale - transform.translateX / transform.scale,
            y: (fromRect.top + fromRect.height / 2 - containerRect.top) / transform.scale - transform.translateY / transform.scale
          };

          const to = {
            x: (toRect.left - containerRect.left) / transform.scale - transform.translateX / transform.scale,
            y: (toRect.top + toRect.height / 2 - containerRect.top) / transform.scale - transform.translateY / transform.scale
          };

          return <FlowArrow key={index} from={from} to={to} label={edge.label} />;
        })}
      </div>
    </div>
  );
};

export default UIFlowCanvas;

