import React, { useState, useEffect } from 'react';
import { PlusIcon, ArrowsPointingOutIcon, XMarkIcon } from './icons';
import { GoogleGenAI, Type } from '@google/genai';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import UIFlowCanvas, { FlowData } from './UIFlowCanvas';

interface ChangeLog {
  id: number;
  date: string;
  title: string;
  description: string;
  diagram?: FlowData;
}

interface GeneratedLog {
    title: string;
    description: string;
    diagram: FlowData;
}

interface ChangeLogModalProps {
  isOpen: boolean;
  onClose: () => void;
}

const MarkdownRenderer: React.FC<{ content: string }> = ({ content }) => (
    <div className="prose prose-sm max-w-none text-gray-700">
        <ReactMarkdown
            remarkPlugins={[remarkGfm]}
            components={{
                h1: ({ node, ...props }) => <h1 className="text-xl font-bold my-3" {...props} />,
                h2: ({ node, ...props }) => <h2 className="text-lg font-semibold my-3" {...props} />,
                h3: ({ node, ...props }) => <h3 className="text-base font-semibold my-2" {...props} />,
                h4: ({ node, ...props }) => <h4 className="text-base font-semibold my-2" {...props} />,
                p: ({ node, ...props }) => <p className="mb-3" {...props} />,
                ul: ({ node, ...props }) => <ul className="list-disc list-inside mb-3" {...props} />,
                ol: ({ node, ...props }) => <ol className="list-decimal list-inside mb-3" {...props} />,
                li: ({ node, ...props }) => <li className="mb-1" {...props} />,
                strong: ({ node, ...props }) => <strong className="font-semibold" {...props} />,
                code: ({node, ...props}) => <code className="bg-gray-200 text-gray-800 rounded px-1 py-0.5 text-xs" {...props} />,
            }}
        >
            {content}
        </ReactMarkdown>
    </div>
);


const ChangeLogModal: React.FC<ChangeLogModalProps> = ({ isOpen, onClose }) => {
  const [logs, setLogs] = useState<ChangeLog[]>([]);
  const [isFormVisible, setIsFormVisible] = useState(false);

  const [userInput, setUserInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [generatedLog, setGeneratedLog] = useState<GeneratedLog | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [diagramToView, setDiagramToView] = useState<FlowData | null>(null);

  useEffect(() => {
    if (isOpen) {
      try {
        const storedLogs = localStorage.getItem('devChangeLogs');
        if (storedLogs) {
          setLogs(JSON.parse(storedLogs));
        }
      } catch (error) {
        console.error("無法從 localStorage 讀取變更紀錄", error);
      }
    }
  }, [isOpen]);

  const saveLogs = (updatedLogs: ChangeLog[]) => {
    try {
      localStorage.setItem('devChangeLogs', JSON.stringify(updatedLogs));
      setLogs(updatedLogs);
    } catch (error) {
      console.error("無法儲存變更紀錄至 localStorage", error);
    }
  };

  const handleGenerateLog = async () => {
    if (!userInput.trim()) {
        setError('請輸入您的需求變更描述。');
        return;
    }
    setIsLoading(true);
    setGeneratedLog(null);
    setError(null);

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: `你是一位專業的前端工程師與 UI/UX 設計師。請根據以下使用者提出的需求變更，產生一份專業的需求變更紀錄。需求描述： "${userInput}"。你的回覆必須是一個**單一且完整的 JSON 物件**，嚴格遵守指定的 schema。在 description 欄位中，請確保所有特殊字元 (例如雙引號或換行符) 都被正確地轉義 (escaped) 以符合 JSON 字串格式。`,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        title: {
                            type: Type.STRING,
                            description: '為這個需求變更產生一個簡潔、專業的標題。'
                        },
                        description: {
                            type: Type.STRING,
                            description: '詳細描述這個需求變更的內容、原因與目的，使用 Markdown 格式，包含標題、列表等。'
                        },
                        diagram: {
                            type: Type.OBJECT,
                            description: '產生一個描述 UI 流程的 JSON 物件。這個物件包含 "nodes" 和 "edges"。此 UI 為**桌面版介面**，因此每個 node 會比較寬。請調整 node 的 position {x, y}，確保節點之間有足夠的水平間距（例如，至少 900 個單位）以避免重疊。可用的 componentName 有： "Login", "MyAccountContent", "TicketManagementContent", "AddVoucherContent", "BasicSettingsContent"。請為元件提供必要的 mock props，例如 isBasicSettingsComplete: true。',
                            properties: {
                                nodes: {
                                    type: Type.ARRAY,
                                    items: {
                                        type: Type.OBJECT,
                                        properties: {
                                            id: { type: Type.STRING },
                                            title: { type: Type.STRING },
                                            componentName: { type: Type.STRING },
                                            props: {
                                                type: Type.OBJECT,
                                                properties: {
                                                    isBasicSettingsComplete: {
                                                        type: Type.BOOLEAN,
                                                        description: "模擬「基本設定」步驟是否已完成的狀態。"
                                                    },
                                                    isVoucherCreationComplete: {
                                                        type: Type.BOOLEAN,
                                                        description: "模擬「建立票券」步驟是否已完成的狀態。"
                                                    }
                                                }
                                            },
                                            position: {
                                                type: Type.OBJECT,
                                                properties: {
                                                    x: { type: Type.NUMBER },
                                                    y: { type: Type.NUMBER },
                                                }
                                            }
                                        }
                                    }
                                },
                                edges: {
                                    type: Type.ARRAY,
                                    items: {
                                        type: Type.OBJECT,
                                        properties: {
                                            from: { type: Type.STRING },
                                            to: { type: Type.STRING },
                                            label: { type: Type.STRING }
                                        }
                                    }
                                }
                            }
                        },
                    },
                    required: ["title", "description", "diagram"]
                },
            },
        });

        const resultText = response.text.trim();
        const logData = JSON.parse(resultText) as GeneratedLog;
        setGeneratedLog(logData);
    } catch (err) {
        console.error("Error generating log:", err);
        setError(`生成紀錄時發生錯誤：${err instanceof Error ? err.message : String(err)}`);
    } finally {
        setIsLoading(false);
    }
  };

  const handleSaveGeneratedLog = () => {
    if (!generatedLog) return;

    const newLog: ChangeLog = {
        id: Date.now(),
        date: new Date().toLocaleString('zh-TW', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }),
        title: generatedLog.title,
        description: generatedLog.description,
        diagram: generatedLog.diagram,
    };
    const updatedLogs = [newLog, ...logs];
    saveLogs(updatedLogs);
    setLogs(updatedLogs); // Immediately update state

    setIsFormVisible(false);
    setGeneratedLog(null);
    setUserInput('');
    setError(null);
  };

  const handleDiscard = () => {
    setGeneratedLog(null);
    setError(null);
  };

  const resetForm = () => {
    setIsFormVisible(false);
    setGeneratedLog(null);
    setUserInput('');
    setError(null);
    setIsLoading(false);
  }

  const openFullscreenDiagram = (diagram: FlowData) => {
    setDiagramToView(diagram);
  };

  const closeFullscreenDiagram = () => {
      setDiagramToView(null);
  };

  return (
    <>
      <div
        className={`fixed inset-0 bg-black bg-opacity-60 z-[100] flex justify-center items-center ${isOpen ? 'visible' : 'invisible'}`}
        aria-labelledby="changelog-modal-title"
        role="dialog"
        aria-modal="true"
        onClick={() => { onClose(); resetForm(); }}
      >
        <div
          className="bg-white w-screen h-screen flex flex-col"
          onClick={e => e.stopPropagation()}
        >
          <div className="p-6 border-b border-gray-200 flex justify-between items-center shrink-0">
            <h3 className="text-lg font-semibold text-gray-900" id="changelog-modal-title">
              需求變更紀錄
            </h3>
            <button
              onClick={() => { onClose(); resetForm(); }}
              className="text-gray-400 hover:text-gray-600"
              aria-label="關閉"
            >
              <XMarkIcon className="w-6 h-6" />
            </button>
          </div>

          <div className="p-6 flex-1 overflow-y-auto">
            {isFormVisible ? (
              <div className="max-w-4xl mx-auto">
                {!generatedLog && !isLoading && (
                    <div className="space-y-4">
                        <h4 className="font-bold text-gray-700">透過對話生成紀錄</h4>
                        <div>
                            <label htmlFor="logPrompt" className="block text-sm font-medium text-gray-700 mb-1">
                                請描述您想記錄的需求變更：
                            </label>
                            <textarea
                                id="logPrompt"
                                rows={4}
                                value={userInput}
                                onChange={(e) => setUserInput(e.target.value)}
                                className="w-full border border-gray-300 rounded-md px-3 py-2 text-sm placeholder-gray-400 focus:ring-1 focus:ring-blue-500 focus:border-blue-500"
                                placeholder="例如：請針對B-01頁面，為新手引導加入完成兩個步驟的提示..."
                            ></textarea>
                        </div>
                        {error && <p className="text-sm text-red-600">{error}</p>}
                        <div className="flex justify-end space-x-3">
                            <button onClick={resetForm} className="bg-gray-200 text-gray-700 px-4 py-2 rounded-md text-sm hover:bg-gray-300">取消</button>
                            <button onClick={handleGenerateLog} className="bg-blue-600 text-white px-4 py-2 rounded-md text-sm hover:bg-blue-700">生成紀錄</button>
                        </div>
                    </div>
                )}
                {isLoading && (
                    <div className="text-center py-10">
                        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500 mx-auto"></div>
                        <p className="mt-4 text-gray-600">正在為您生成紀錄，請稍候...</p>
                    </div>
                )}
                {generatedLog && !isLoading && (
                    <div className="space-y-4">
                        <h4 className="font-bold text-gray-700">已生成紀錄預覽</h4>
                        <div className="bg-gray-50 border border-gray-200 p-4 rounded-lg space-y-4">
                            <div>
                                <h5 className="font-bold text-gray-800 text-xl mb-4">{generatedLog.title}</h5>
                            </div>
                            <div>
                                <MarkdownRenderer content={generatedLog.description} />
                            </div>
                            {generatedLog.diagram && (
                                <div className="mt-4 p-4 bg-white border rounded-md">
                                    <div className="flex justify-between items-center mb-2">
                                        <h6 className="text-sm font-semibold text-gray-600">流程圖</h6>
                                        <button 
                                            onClick={() => openFullscreenDiagram(generatedLog.diagram!)}
                                            className="text-gray-500 hover:text-gray-800 p-1 rounded-full hover:bg-gray-200 transition-colors"
                                            aria-label="全螢幕預覽"
                                        >
                                            <ArrowsPointingOutIcon className="w-5 h-5" />
                                        </button>
                                    </div>
                                     <div className="h-[70vh] w-full bg-slate-100 rounded-lg overflow-hidden">
                                          <UIFlowCanvas flowData={generatedLog.diagram} />
                                     </div>
                                </div>
                            )}
                        </div>
                        {error && <p className="text-sm text-red-600 mt-2">{error}</p>}
                        <div className="flex justify-end space-x-3 pt-2">
                            <button onClick={handleDiscard} className="bg-gray-200 text-gray-700 px-4 py-2 rounded-md text-sm hover:bg-gray-300">重新生成</button>
                            <button onClick={handleSaveGeneratedLog} className="bg-green-600 text-white px-4 py-2 rounded-md text-sm hover:bg-green-700">儲存此紀錄</button>
                        </div>
                    </div>
                )}
              </div>
            ) : (
              <div className="max-w-4xl mx-auto">
                <div className="flex justify-end mb-4">
                  <button 
                    onClick={() => setIsFormVisible(true)}
                    className="flex items-center bg-green-600 text-white px-4 py-2 rounded-md text-sm hover:bg-green-700"
                  >
                    <PlusIcon className="w-5 h-5 mr-1" />
                    新增紀錄
                  </button>
                </div>

                {logs.length > 0 ? (
                  <div className="space-y-4">
                    {logs.map(log => (
                      <div key={log.id} className="bg-gray-50 border border-gray-200 p-4 rounded-lg">
                        <div className="flex justify-between items-center mb-2">
                          <h5 className="font-bold text-gray-800 text-lg">{log.title}</h5>
                          <span className="text-xs text-gray-500">{log.date}</span>
                        </div>
                        <MarkdownRenderer content={log.description} />
                        {log.diagram && (
                            <div className="mt-4 p-4 bg-white border rounded-md">
                                <div className="flex justify-between items-center mb-2">
                                    <h6 className="text-sm font-semibold text-gray-600">流程圖</h6>
                                    <button 
                                        onClick={() => openFullscreenDiagram(log.diagram!)}
                                        className="text-gray-500 hover:text-gray-800 p-1 rounded-full hover:bg-gray-200 transition-colors"
                                        aria-label="全螢幕預覽"
                                    >
                                        <ArrowsPointingOutIcon className="w-5 h-5" />
                                    </button>
                                </div>
                                <div className="h-[70vh] w-full bg-slate-100 rounded-lg overflow-hidden">
                                  <UIFlowCanvas flowData={log.diagram} />
                                </div>
                            </div>
                        )}
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="text-center py-10 text-gray-500">
                    <p>目前沒有任何變更紀錄。</p>
                    <p className="mt-1">點擊「新增紀錄」來建立第一筆吧！</p>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      </div>

      {diagramToView && (
          <div className="fixed inset-0 bg-black/80 z-[110] flex flex-col p-4" aria-modal="true" role="dialog">
              <div className="flex justify-end mb-2">
                  <button 
                      onClick={closeFullscreenDiagram}
                      className="text-white hover:text-gray-300 p-2 rounded-full bg-white/10 hover:bg-white/20 transition-colors"
                      aria-label="關閉全螢幕"
                  >
                      <XMarkIcon className="w-7 h-7" />
                  </button>
              </div>
              <div className="flex-1 bg-slate-100 rounded-lg overflow-hidden">
                  <UIFlowCanvas flowData={diagramToView} />
              </div>
          </div>
      )}
    </>
  );
};

export default ChangeLogModal;

import React, { useState, useMemo } from 'react';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import MyAccountContent from './components/MyAccountContent';
import BasicSettingsContent from './components/BasicSettingsContent';
import TicketManagementContent from './components/TicketManagementContent';
import AddVoucherContent from './components/AddVoucherContent';
import Login from './components/Login';
import Register from './components/Register';
import VerifyPhone from './components/VerifyPhone';
import StoreInfo from './components/StoreInfo';
import RegistrationComplete from './components/RegistrationComplete';
import DevProgressButton from './components/DevProgressButton';
import DevProgressModal from './components/DevProgressModal';
import ChangeLogButton from './components/ChangeLogButton';
import ChangeLogModal from './components/ChangeLogModal';
import FlowCaptureButton from './components/FlowCaptureButton';
import FlowCaptureTool from './components/FlowCaptureTool';
import { CapturedStep } from './components/FlowCaptureTool';

export type Page = 'myAccount' | 'basicSettings' | 'ticketManagement' | 'addVoucher';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [authPage, setAuthPage] = useState<'login' | 'register' | 'verifyPhone' | 'storeInfo' | 'registrationComplete'>('login');
  const [currentPage, setCurrentPage] = useState<Page>('myAccount');
  const [isBasicSettingsComplete, setIsBasicSettingsComplete] = useState(false);
  const [isVoucherCreationComplete, setIsVoucherCreationComplete] = useState(false);
  const [isDevModalOpen, setIsDevModalOpen] = useState(false);
  const [isChangeLogModalOpen, setIsChangeLogModalOpen] = useState(false);
  const [isCaptureModeActive, setIsCaptureModeActive] = useState(false);
  const [initialLogAction, setInitialLogAction] = useState<string | null>(null);

  const currentPageInfo = useMemo(() => {
    if (!isLoggedIn) {
      switch (authPage) {
        case 'login': return { id: 'P-01', name: '登入頁' };
        case 'register': return { id: 'P-02', name: '註冊頁' };
        case 'verifyPhone': return { id: 'P-03', name: '驗證手機號碼' };
        case 'storeInfo': return { id: 'P-04', name: '填寫店家資訊' };
        case 'registrationComplete': return { id: 'P-05', name: '恭喜完成註冊' };
        default: return { id: 'P-01', name: '登入頁' };
      }
    } else {
      switch (currentPage) {
        case 'myAccount': return { id: 'B-01', name: '我的帳號' };
        case 'basicSettings': return { id: 'B-02', name: '基本設定' };
        case 'ticketManagement': return { id: 'B-03', name: '票券管理' };
        case 'addVoucher': return { id: 'B-04', name: '新增優惠券' };
        default: return { id: 'B-01', name: '我的帳號' };
      }
    }
  }, [isLoggedIn, authPage, currentPage]);

  const handleLoginSuccess = () => {
    setIsLoggedIn(true);
  };

  const handleSitemapNavigate = (pageId: string) => {
    switch (pageId) {
      // Auth Pages
      case 'P-01':
        setIsLoggedIn(false);
        setAuthPage('login');
        break;
      case 'P-02':
        setIsLoggedIn(false);
        setAuthPage('register');
        break;
      case 'P-03':
        setIsLoggedIn(false);
        setAuthPage('verifyPhone');
        break;
      case 'P-04':
        setIsLoggedIn(false);
        setAuthPage('storeInfo');
        break;
      case 'P-05':
        setIsLoggedIn(false);
        setAuthPage('registrationComplete');
        break;
      // Backend Pages
      case 'B-01':
        setIsLoggedIn(true);
        setCurrentPage('myAccount');
        break;
      case 'B-02':
        setIsLoggedIn(true);
        setCurrentPage('basicSettings');
        break;
      case 'B-03':
        setIsLoggedIn(true);
        setCurrentPage('ticketManagement');
        break;
      case 'B-04':
        setIsLoggedIn(true);
        setCurrentPage('addVoucher');
        break;
      default:
        return; // Do nothing for unhandled or future pages
    }
    setIsDevModalOpen(false); // Close modal after navigation
  };

  const handleCaptureComplete = (steps: CapturedStep[]) => {
    const formattedSteps = steps.map((step, index) => `${index + 1}. 元件名稱: "${step.name}" (ID: ${step.id})`).join('\n');
    const action = `使用者依序點擊了以下元件來完成一項操作：\n${formattedSteps}\n\n請根據這個操作流程，為我生成一份專業的需求變更紀錄與對應的 UI 流程圖。`;
    setInitialLogAction(action);
    setIsChangeLogModalOpen(true);
    setIsCaptureModeActive(false);
  };

  const renderContent = () => {
    switch (currentPage) {
      case 'ticketManagement':
        return <TicketManagementContent setCurrentPage={setCurrentPage} />;
      case 'addVoucher':
        return <AddVoucherContent 
                  setCurrentPage={setCurrentPage} 
                  setIsVoucherCreationComplete={setIsVoucherCreationComplete}
                  isBasicSettingsComplete={isBasicSettingsComplete}
                  isVoucherCreationComplete={isVoucherCreationComplete}
                />;
      case 'basicSettings':
        return <BasicSettingsContent 
                  setIsBasicSettingsComplete={setIsBasicSettingsComplete} 
                  setCurrentPage={setCurrentPage}
                  isVoucherCreationComplete={isVoucherCreationComplete} 
                  isBasicSettingsComplete={isBasicSettingsComplete}
                />;
      case 'myAccount':
      default:
        return <MyAccountContent 
                  setCurrentPage={setCurrentPage} 
                  isBasicSettingsComplete={isBasicSettingsComplete} 
                  isVoucherCreationComplete={isVoucherCreationComplete}
                />;
    }
  };

  const renderAuthContent = () => {
    switch (authPage) {
      case 'register':
        return <Register onSwitchToLogin={() => setAuthPage('login')} onRegisterSuccess={() => setAuthPage('verifyPhone')} />;
      case 'verifyPhone':
        return <VerifyPhone onSwitchToRegister={() => setAuthPage('register')} onVerifySuccess={() => setAuthPage('storeInfo')} />;
      case 'storeInfo':
        return <StoreInfo onBackToVerify={() => setAuthPage('verifyPhone')} onStoreInfoSuccess={() => setAuthPage('registrationComplete')} />;
      case 'registrationComplete':
        return <RegistrationComplete onComplete={handleLoginSuccess} />;
      case 'login':
      default:
        return <Login onLoginSuccess={handleLoginSuccess} onSwitchToRegister={() => setAuthPage('register')} />;
    }
  }

  const handleCloseChangeLog = () => {
    setIsChangeLogModalOpen(false);
    setInitialLogAction(null); // Reset action when modal closes
  }

  return (
    <>
      {isLoggedIn ? (
        <div className="flex h-screen bg-gray-100 font-sans antialiased text-gray-800">
          <Sidebar currentPage={currentPage} setCurrentPage={setCurrentPage} />
          <div className="flex-1 flex flex-col overflow-hidden">
            <Header currentPage={currentPage} setCurrentPage={setCurrentPage} />
            <main className="flex-1 overflow-x-hidden overflow-y-auto bg-[#f0f2f5]">
              <div className="container mx-auto px-6 py-8">
                {renderContent()}
              </div>
            </main>
          </div>
        </div>
      ) : (
        renderAuthContent()
      )}
      <div className="fixed bottom-6 right-6 z-50 flex items-center space-x-3">
        <FlowCaptureButton onClick={() => setIsCaptureModeActive(true)} />
        <ChangeLogButton onClick={() => setIsChangeLogModalOpen(true)} />
        <DevProgressButton 
          onClick={() => setIsDevModalOpen(true)}
          pageId={currentPageInfo.id}
          pageName={currentPageInfo.name}
        />
      </div>
      <DevProgressModal isOpen={isDevModalOpen} onClose={() => setIsDevModalOpen(false)} onNavigate={handleSitemapNavigate} />
      <ChangeLogModal 
        isOpen={isChangeLogModalOpen} 
        onClose={handleCloseChangeLog} 
        initialUserAction={initialLogAction}
      />
      {isCaptureModeActive && (
        <FlowCaptureTool 
          onCancel={() => setIsCaptureModeActive(false)}
          onComplete={handleCaptureComplete}
        />
      )}
    </>
  );
};

export default App;

